import React, { useContext } from 'react';
import { ThemeContext } from '../theme/ThemeProvider';
import './Achievements.css';

const categories = [
  {
    id: 'prestasi',
    label: 'Prestasi',
    icon: '🏆',
    color: '#f59e0b',
    items: [
      { year: '2026', text: 'Juara 3 Capstone Project Informatika — Best Presentation' },
      { year: '2025', text: 'Lolos Pendanaan P2MW — Tim ChatNiaga AI' },
      { year: '2025', text: 'Finalis KMI Expo — Tim ChatNiaga AI' },
    ],
  },
  {
    id: 'komunitas',
    label: 'Komunitas',
    icon: '🌐',
    color: '#00bfbf',
    items: [
      { year: '2025', text: 'Builder Community Network Official Dicoding Batch 2' },
      { year: '2025', text: 'Course Experience Tester Official Dicoding' },
      { year: '2024', text: 'Staff Informatic Study Club — Bidang Web Development' },
    ],
  },
  {
    id: 'organisasi',
    label: 'Organisasi',
    icon: '⚡',
    color: '#8b5cf6',
    items: [
      
      { year: '2025', text: 'Staff BEM KM — Kementrian Advokesma (Aspirasi Mahasiswa)' },
      { year: '2025', text: 'Ketua Divisi Acara Pengabdian Masyarakat BEM KM UNIMUS' },
      { year: '2025', text: 'Ketua Panitia AdvoSkill — Pelatihan Penyampaian Aspirasi' },
      { year: '2024', text: 'Staff Acara Masta PMB Universitas Muhammadiyah Semarang' },
      { year: '2024', text: 'Staff Department Perhubungan BEM FTIK UNIMUS' },
    ],
  },
];

const Achievements = () => {
  const { theme } = useContext(ThemeContext);

  return (
    <section id="achievements" className={`achievements-section ${theme}`}>
      {/* Header */}
      <div className="achievements-header">
        <span className="achievements-line" />
        <h2 className="achievements-title">Pencapaian Lainnya</h2>
        <span className="achievements-line" />
      </div>

      {/* Category Columns */}
      <div className="achievements-grid">
        {categories.map((cat) => (
          <div className="achievement-col" key={cat.id}>
            {/* Column Header */}
            <div className="achievement-col-header" style={{ borderColor: cat.color }}>
              <span className="achievement-cat-icon">{cat.icon}</span>
              <span className="achievement-cat-label" style={{ color: cat.color }}>
                {cat.label}
              </span>
            </div>

            {/* Items */}
            <div className="achievement-items">
              {cat.items.map((item, i) => (
                <div
                  className="achievement-item"
                  key={i}
                  style={{ '--accent': cat.color }}
                >
                  <span className="achievement-year">{item.year}</span>
                  <p className="achievement-text">{item.text}</p>
                </div>
              ))}
            </div>
          </div>
        ))}
      </div>
    </section>
  );
};

export default Achievements;
