import React, { useContext, useState, useEffect } from "react";
import { ThemeContext } from "../theme/ThemeProvider";
import Slider from "react-slick";

import "slick-carousel/slick/slick.css";
import "slick-carousel/slick/slick-theme.css";

import "./Experience.css"; 

import p2mw from "../../assets/images/p2mw.jpg";
import bemkm from "../../assets/images/bemkm.jpg";
import bemftik from "../../assets/images/bemftik.jpeg";



const experienceData = [
  {
    id: 1,
    title: "BEM KM UNIMUS",
    organization: "Universitas Muhammadiyah Semarang",
    date: "2024 - 2025",
    description: "Kementrian Advokesma, Staff Dirjen Kesejahteraan Mahasiswa.",
    image: bemkm,
  },
  {
    id: 2,
    title: "Hibah P2MW-Bisnis Digital & Finalis KMI Expo",
    organization: "Program Pembinaan Mahasiswa Wirausaha",
    date: "2025",
    description: "FullStack Web Developer",
    image: p2mw,
  },
  {
    id: 3,
    title: "BEM FTIK",
    organization: "BEM Fakultas Teknik dan Ilmu Komputer",
    date: "2024",
    description: "Menjadi staff BEM FTIK.",
    image: bemftik,
  },
];

const Experience = () => {
  const { theme } = useContext(ThemeContext);

  // 2. Buat state untuk mengatur jumlah slide
  const [slidesToShow, setSlidesToShow] = useState(2);

  useEffect(() => {
    // 3. Fungsi untuk memeriksa lebar layar
    const handleResize = () => {
      if (window.innerWidth <= 1024) {
        setSlidesToShow(1); // Jika layar tablet atau lebih kecil, tampilkan 1
      } else {
        setSlidesToShow(2); // Jika layar desktop, tampilkan 2
      }
    };

    // Panggil fungsi saat komponen pertama kali dimuat
    handleResize();

    // Tambahkan event listener untuk memantau perubahan ukuran layar
    window.addEventListener('resize', handleResize);

    // Cleanup: Hapus event listener saat komponen dibongkar
    return () => window.removeEventListener('resize', handleResize);
  }, []); // [] berarti efek ini hanya berjalan sekali saat komponen dimuat

  // 4. Perbarui pengaturan slider
  const sliderSettings = {
    dots: true,
    infinite: true,
    speed: 500,
    slidesToShow: slidesToShow, // <-- Gunakan state di sini
    slidesToScroll: 1,
    // Kita tidak lagi butuh 'responsive' karena sudah diatur manual
  };
  
  const renderCards = () =>
    experienceData.map((exp, index) => (
        <div className="experience-card-wrapper" key={exp.id}>
            <div 
                className="experience-card"
                data-aos="fade-up"
                data-aos-delay={index * 200}
            >
                <img src={exp.image} alt={exp.title} className="experience-card-img" />
                <div className="experience-card-content">
                    <h3 className="experience-card-title">{exp.title}</h3>
                    <p className="experience-card-org">{exp.organization}</p>
                    <p className="experience-card-date">{exp.date}</p>
                    <p className="experience-card-desc">{exp.description}</p>
                </div>
            </div>
        </div>
    ));

  return (
    <section id="experience" className={`experience-section ${theme}`}>
      <div className="experience-container">
        <h2 className="experience-title" data-aos="fade-down">
          Pengalaman Saya
        </h2>
        
        {experienceData.length > slidesToShow ? (
          <Slider {...sliderSettings}>{renderCards()}</Slider>
        ) : (
          <div className="experience-grid">{renderCards()}</div>
        )}
      </div>
    </section>
  );
};

export default Experience;
