import React, { useState } from "react";
import { Typography } from "@material-ui/core";
import { useNav } from "./NavContext";
import "./SideNavbar.css";

const navLinks = [
  { href: "#", name: "Beranda" },
  { href: "#about", name: "Tentang" },
  { href: "#skills", name: "Skill" },
  { href: "#works", name: "Proyek" },
  { href: "#experience", name: "Pengalaman" },
  { href: "#achievements", name: "Pencapaian" },
  { href: "#contact", name: "Kontak" },
];

export const SideNavbar = () => {
  const { isNavOpen, closeNav } = useNav();
  const [activeNav, setActiveNav] = useState("#");

  const handleNavClick = (href) => {
    setActiveNav(href);
    closeNav();
  };

  return (
    <nav className={isNavOpen ? "" : "nav-hidden"}>
      {navLinks.map((link) => (
        <a
          href={link.href}
          key={link.href}
          onClick={() => handleNavClick(link.href)}
          className={activeNav === link.href ? "active" : ""}
        >
          <Typography>{link.name}</Typography>
        </a>
      ))}
    </nav>
  );
};